public class PinCheck {
    // true only for exactly four ASCII digits '0'-'9'
    static boolean isValidPin(String s) {
        if (s == null || s.length() != 4) return false;
        for (int i = 0; i < 4; i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') return false;
        }
        return true;
    }

    public static void main(String[] args) {
        String[] input = {"1234", "0000", "9999", "123", "12345", "", "12a4",
                          " 123", "12.3", "-123", "\u09E7\u09E8\u09E9\u09EA", null};
        boolean[] expected = {true, true, true, false, false, false, false,
                              false, false, false, false, false};
        int pass = 0;
        for (int i = 0; i < input.length; i++) {
            boolean got = isValidPin(input[i]);
            boolean ok = (got == expected[i]);
            if (ok) pass++;
            System.out.println("TC" + (i + 1) + " -> " + got + (ok ? " PASS" : " FAIL"));
        }
        System.out.println(pass + "/" + input.length + " passed");
    }
}

