import java.util.ArrayList;
import java.util.List;

public class FolderSize {
    interface Node { String name(); long size(); void print(String indent); }

    static class FileLeaf implements Node {
        private final String name; private final long kb;
        FileLeaf(String name, long kb) { this.name = name; this.kb = kb; }
        public String name() { return name; }
        public long size() { return kb; }
        public void print(String indent) { System.out.println(indent + name + " (" + kb + " KB)"); }
    }

    static class Folder implements Node {
        private final String name; private final List<Node> children = new ArrayList<>();
        Folder(String name) { this.name = name; }
        Folder add(Node n) { children.add(n); return this; }
        public String name() { return name; }
        public long size() { long s = 0; for (Node c : children) s += c.size(); return s; }
        public void print(String indent) {
            System.out.println(indent + name + "/ (" + size() + " KB)");
            for (Node c : children) c.print(indent + "  ");
        }
    }

    public static void main(String[] args) {
        Folder reports = new Folder("reports")
            .add(new FileLeaf("jan.pdf", 120))
            .add(new FileLeaf("feb.pdf", 95));
        Folder root = new Folder("tender")
            .add(new FileLeaf("boq.xlsx", 40))
            .add(reports)
            .add(new Folder("empty"));
        root.print("");
        System.out.println("total = " + root.size() + " KB");
    }
}

Output (compiled and run with javac/java 21):
tender/ (255 KB)
  boq.xlsx (40 KB)
  reports/ (215 KB)
    jan.pdf (120 KB)
    feb.pdf (95 KB)
  empty/ (0 KB)
total = 255 KB

The client calls size() on any Node without checking whether it is a file or a folder; Folder delegates recursively to its children (40 + 120 + 95 + 0 = 255).

