import java.util.Arrays;

public class SortContext {
    interface SortStrategy { String name(); void sort(int[] a); }

    static class BubbleSort implements SortStrategy {
        public String name() { return "Bubble"; }
        public void sort(int[] a) {
            for (int i = 0; i < a.length - 1; i++)
                for (int j = 0; j < a.length - 1 - i; j++)
                    if (a[j] > a[j + 1]) { int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t; }
        }
    }
    static class InsertionSort implements SortStrategy {
        public String name() { return "Insertion"; }
        public void sort(int[] a) {
            for (int i = 1; i < a.length; i++) {
                int key = a[i], j = i - 1;
                while (j >= 0 && a[j] > key) { a[j + 1] = a[j]; j--; }
                a[j + 1] = key;
            }
        }
    }
    static class QuickSort implements SortStrategy {
        public String name() { return "Quick"; }
        public void sort(int[] a) { qs(a, 0, a.length - 1); }
        private void qs(int[] a, int lo, int hi) {
            if (lo >= hi) return;
            int p = a[hi], i = lo;
            for (int j = lo; j < hi; j++) if (a[j] < p) { int t = a[i]; a[i] = a[j]; a[j] = t; i++; }
            int t = a[i]; a[i] = a[hi]; a[hi] = t;
            qs(a, lo, i - 1); qs(a, i + 1, hi);
        }
    }

    private SortStrategy strategy;
    void setStrategy(SortStrategy s) { strategy = s; }
    int[] run(int[] data) {
        int[] copy = Arrays.copyOf(data, data.length);
        strategy.sort(copy);
        return copy;
    }

    // choose by input size: small lists -> insertion, large -> quick
    static SortStrategy choose(int n) { return n <= 10 ? new InsertionSort() : new QuickSort(); }

    public static void main(String[] args) {
        int[] data = {42, 7, 19, 3, 25, 11};
        SortContext ctx = new SortContext();
        for (SortStrategy s : new SortStrategy[]{new BubbleSort(), new InsertionSort(), new QuickSort()}) {
            ctx.setStrategy(s);
            System.out.println(s.name() + ": " + Arrays.toString(ctx.run(data)));
        }
        System.out.println("auto(6) -> " + choose(6).name() + ", auto(5000) -> " + choose(5000).name());
        System.out.println("original: " + Arrays.toString(data));
    }
}

Output (compiled and run with javac/java 21):
Bubble: [3, 7, 11, 19, 25, 42]
Insertion: [3, 7, 11, 19, 25, 42]
Quick: [3, 7, 11, 19, 25, 42]
auto(6) -> Insertion, auto(5000) -> Quick
original: [42, 7, 19, 3, 25, 11]

Why Strategy: each algorithm is encapsulated behind one interface, so the context swaps algorithms at run time without if-else chains, and a new algorithm (merge sort) is added as a new class without changing SortContext (open–closed principle). run() sorts a copy, so the caller's array is unchanged.

