import java.util.*;

public class Cpm {
    record Act(String id, int dur, List<String> pred) {}

    public static void main(String[] args) {
        // activities listed in an order where every predecessor comes first
        List<Act> acts = List.of(
            new Act("A", 3, List.of()),
            new Act("B", 4, List.of("A")),
            new Act("C", 2, List.of("A")),
            new Act("D", 5, List.of("C")),
            new Act("E", 3, List.of("B", "D")),
            new Act("F", 4, List.of("B")));
        Map<String, Integer> es = new HashMap<>(), ef = new HashMap<>(), ls = new HashMap<>(), lf = new HashMap<>();

        for (Act a : acts) {                                   // forward pass
            int start = 0;
            for (String p : a.pred()) start = Math.max(start, ef.get(p));
            es.put(a.id(), start);
            ef.put(a.id(), start + a.dur());
        }
        int project = Collections.max(ef.values());

        for (int i = acts.size() - 1; i >= 0; i--) {          // backward pass
            Act a = acts.get(i);
            int finish = project;
            for (Act s : acts) if (s.pred().contains(a.id())) finish = Math.min(finish, ls.get(s.id()));
            lf.put(a.id(), finish);
            ls.put(a.id(), finish - a.dur());
        }

        System.out.println("Act  ES  EF  LS  LF  Float");
        StringBuilder path = new StringBuilder();
        for (Act a : acts) {
            int fl = ls.get(a.id()) - es.get(a.id());
            System.out.printf("%-4s %2d  %2d  %2d  %2d  %3d%n", a.id(), es.get(a.id()), ef.get(a.id()),
                              ls.get(a.id()), lf.get(a.id()), fl);
            if (fl == 0) path.append(path.length() == 0 ? "" : "-").append(a.id());
        }
        System.out.println("Project duration = " + project + " days");
        System.out.println("Critical path = " + path);
    }
}

